import numpy as np
from scipy.optimize import minimize

def _force_directed_seed(seed):
    """
    Generates an initial configuration using a physics-based force-directed layout.
    """
    np.random.seed(seed)
    n_circles = 26

    # 1. Initialization: Randomly place circles
    centers = np.random.rand(n_circles, 2)
    # Start with a plausible average radius for force calculations
    radii = np.full(n_circles, 0.1) 

    # 2. Force Simulation
    n_steps = 300
    learning_rate = 0.01

    for step in range(n_steps):
        force_vectors = np.zeros_like(centers)

        # Repulsion forces between circles
        for i in range(n_circles):
            for j in range(i + 1, n_circles):
                delta = centers[j] - centers[i]
                dist_sq = np.sum(delta**2)
                if dist_sq == 0: dist_sq = 1e-6 # Avoid division by zero
                dist = np.sqrt(dist_sq)
                rad_sum = radii[i] + radii[j]

                if dist < rad_sum:
                    overlap = rad_sum - dist
                    # Force is proportional to overlap and pushes circles apart
                    force = (delta / dist) * overlap
                    force_vectors[i] -= force
                    force_vectors[j] += force

        # Repulsion forces from walls
        for i in range(n_circles):
            x, y = centers[i]
            r = radii[i]
            if x - r < 0: force_vectors[i, 0] += (r - x)
            if x + r > 1: force_vectors[i, 0] -= (x + r - 1)
            if y - r < 0: force_vectors[i, 1] += (r - y)
            if y + r > 1: force_vectors[i, 1] -= (y + r - 1)

        # 3. Update positions
        centers += learning_rate * force_vectors
        centers = np.clip(centers, 0, 1) # Keep centers within bounds

    # The radii from the simulation are not used, SLSQP will find optimal ones
    initial_radii = np.full(n_circles, 0.05) # Small initial radii for SLSQP
    initial_guess = np.zeros(n_circles * 3)
    initial_guess[0::3] = centers[:, 0]
    initial_guess[1::3] = centers[:, 1]
    initial_guess[2::3] = initial_radii
    return initial_guess

def _run_slsqp_optimization(initial_guess):
    n_circles = 26
    def objective(p): return -np.sum(p[2::3])
    constraints = []
    for i in range(n_circles):
        constraints.extend([
            {'type': 'ineq', 'fun': lambda p, i=i: p[i*3] - p[i*3+2]}, {'type': 'ineq', 'fun': lambda p, i=i: 1-p[i*3]-p[i*3+2]},
            {'type': 'ineq', 'fun': lambda p, i=i: p[i*3+1]-p[i*3+2]}, {'type': 'ineq', 'fun': lambda p, i=i: 1-p[i*3+1]-p[i*3+2]}
        ])
        for j in range(i + 1, n_circles):
            constraints.append({'type': 'ineq', 'fun': lambda p, i=i, j=j: (p[i*3]-p[j*3])**2 + (p[i*3+1]-p[j*3+1])**2 - (p[i*3+2]+p[j*3+2])**2})
    bounds = []
    for i in range(n_circles): bounds.extend([(0,1), (0,1), (1e-6, 0.5)])
    result = minimize(objective, initial_guess, method='SLSQP', bounds=bounds, constraints=constraints, options={'maxiter': 250})
    p = result.x
    centers = np.vstack((p[0::3], p[1::3])).T; radii = p[2::3]
    return centers, radii

def _ensure_validity(centers, radii):
    n = centers.shape[0]; safety_factor = 1.0 - 1e-9
    for i in range(n): radii[i] = min(radii[i], centers[i,0], 1-centers[i,0], centers[i,1], 1-centers[i,1])
    for _ in range(10):
        violations = 0
        for i in range(n):
            for j in range(i + 1, n):
                dist = np.linalg.norm(centers[i] - centers[j])
                rad_sum = radii[i] + radii[j]
                if dist < rad_sum:
                    violations+=1;
                    if rad_sum > 0: scale = (dist/rad_sum)*safety_factor; radii[i]*=scale; radii[j]*=scale
        if violations == 0: break
    return centers, np.maximum(radii, 0)

def construct_packing() -> tuple:
    num_starts = 16
    best_score = -1
    best_packing = (None, None)

    for i in range(num_starts):
        initial_guess = _force_directed_seed(seed=i)
        centers, radii = _run_slsqp_optimization(initial_guess)
        centers, radii = _ensure_validity(centers, radii)
        current_score = np.sum(radii)

        if current_score > best_score:
            best_score = current_score
            best_packing = (centers, radii)

    return best_packing
